// Model: lock service with fencing tokens. One lock record (CAS), clients race with
// out-of-order times. A resource accepts a write only if its token was issued and
// is not lower than the highest accepted token.
type tLease = (holder: int, token: int, expiry: int);
event eWrite: (token: int, client: int);
event eAccepted: (token: int);

machine Lock {
  var last: int; var hasLease: bool; var lease: tLease; var ttl: int;
  start state Init {
    entry (t: int) { ttl = t; last = 0; hasLease = false; goto Serve; }
  }
  state Serve { on null do { } }
  fun Acquire(client: int, now: int): int {
    if (hasLease && now < lease.expiry) {
      if (lease.holder == client) { return lease.token; }
      return -1;
    }
    last = last + 1;
    lease = (holder = client, token = last, expiry = now + ttl);
    hasLease = true;
    return last;
  }
}

// Spec: accepted writes carry non-decreasing tokens.
spec FencingMonotonic observes eAccepted {
  var maxTok: int;
  start state S {
    on eAccepted do (e: (token: int)) {
      assert e.token >= maxTok, format("accepted token {0} after {1}", e.token, maxTok);
      maxTok = e.token;
    }
  }
}

machine Resource {
  var maxTok: int; var issued: int;
  start state Init { entry { maxTok = 0; goto Serve; } }
  state Serve {
    on eWrite do (w: (token: int, client: int)) {
      if (w.token < 1 || w.token > issued || w.token < maxTok) { return; }
      maxTok = w.token;
      announce eAccepted, (token = w.token,);
    }
  }
}
